// Source: https://ui.shadcn.com/r/styles/new-york-v4/button.json (MIT)
import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Slot } from "radix-ui"
import "./minecraft-button.css"
import { minecraftGlyphs } from "./minecraft-font"

function bitmapText(content: React.ReactNode): React.ReactNode {
  if (Array.isArray(content)) return content.map((child, index) => <React.Fragment key={index}>{bitmapText(child)}</React.Fragment>)
  if (typeof content !== "string" && typeof content !== "number") return content
  const text = String(content)
  if (!/^[\x20-\x7e]*$/.test(text)) return content
  return <span className="mc-text">
    <span className="mc-text-pixels" aria-hidden="true">
      {Array.from(text, (char, index) => {
        const [x, y, advance] = minecraftGlyphs[char.charCodeAt(0) - 32]
        return <span key={index} className="mc-glyph" style={{
          "--mc-glyph-x": x, "--mc-glyph-y": y, "--mc-advance": advance,
          visibility: char === " " ? "hidden" : undefined,
        } as React.CSSProperties} />
      })}
    </span>
    <span className="mc-text-accessible">{text}</span>
  </span>
}

const webButtonClasses = "gap-2 rounded-md text-sm font-medium transition-all focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-50"

const buttonVariants = cva(
  "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap outline-none disabled:pointer-events-none aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "mc-button",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "",
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    compoundVariants: [
      { variant: ["destructive", "outline", "secondary", "ghost", "link"], className: webButtonClasses },
      { variant: ["destructive", "outline", "secondary", "ghost", "link"], size: "default", className: "h-9 px-4 py-2 has-[>svg]:px-3" },
    ],
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  scale = 2,
  style,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    scale?: 1 | 2 | 3
  }) {
  const Comp = asChild ? Slot.Root : "button"
  const skin = (content: React.ReactNode) => variant === "default" ? <>
    <span className="mc-button-surface" aria-hidden="true">
      {Array.from({ length: 9 }, (_, index) => <span key={index} />)}
    </span>
    <span className="mc-button-label">{bitmapText(content)}</span>
  </> : content
  const content = asChild && React.isValidElement<{ children?: React.ReactNode }>(children)
    ? React.cloneElement(children, {}, skin(children.props.children))
    : skin(children)

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      style={{ "--mc-scale": scale, ...style } as React.CSSProperties}
      {...props}
    >{content}</Comp>
  )
}

export { Button, buttonVariants }

@layer theme, base, components, utilities;
@import "./minecraft-assets.css";

@layer components {
  .mc-button {
    --mc-pixel: calc(1px * var(--mc-scale, 2));
    --mc-ink: #fff;
    --mc-shadow: #3f3f3f;
    --mc-image: var(--mc-normal-image);
    --mc-border: var(--mc-normal-border);
    --mc-border-px: calc(var(--mc-border) * var(--mc-pixel));
    --mc-tile-width: calc((200 - 2 * var(--mc-border)) * var(--mc-pixel));
    --mc-tile-height: calc((20 - 2 * var(--mc-border)) * var(--mc-pixel));
    --mc-piece-0: var(--mc-normal-0);
    --mc-piece-1: var(--mc-normal-1);
    --mc-piece-2: var(--mc-normal-2);
    --mc-piece-3: var(--mc-normal-3);
    --mc-piece-4: var(--mc-normal-4);
    --mc-piece-5: var(--mc-normal-5);
    --mc-piece-6: var(--mc-normal-6);
    --mc-piece-7: var(--mc-normal-7);
    --mc-piece-8: var(--mc-normal-8);
    width: calc(200 * var(--mc-pixel));
    height: calc(20 * var(--mc-pixel));
    min-width: calc(6 * var(--mc-pixel));
    min-height: calc(6 * var(--mc-pixel));
    padding: 0;
    border: 0;
    border-radius: 0;
    background: var(--mc-image) center / 100% 100% no-repeat;
    color: var(--mc-ink);
    font-family: "Minecraft Pilot 26.2", monospace;
    font-size: calc(8 * var(--mc-pixel));
    font-weight: 400;
    font-style: normal;
    font-synthesis: none;
    font-kerning: none;
    letter-spacing: 0;
    line-height: 1;
    text-transform: none;
    text-decoration: none;
    text-shadow: var(--mc-pixel) var(--mc-pixel) 0 var(--mc-shadow);
    image-rendering: pixelated;
    cursor: pointer;
  }
  .mc-button:is(:hover, :focus-visible):not(:disabled, [aria-disabled="true"]) {
    --mc-image: var(--mc-highlighted-image);
    --mc-piece-0: var(--mc-highlighted-0);
    --mc-piece-1: var(--mc-highlighted-1);
    --mc-piece-2: var(--mc-highlighted-2);
    --mc-piece-3: var(--mc-highlighted-3);
    --mc-piece-4: var(--mc-highlighted-4);
    --mc-piece-5: var(--mc-highlighted-5);
    --mc-piece-6: var(--mc-highlighted-6);
    --mc-piece-7: var(--mc-highlighted-7);
    --mc-piece-8: var(--mc-highlighted-8);
  }
  .mc-button:is(:disabled, [aria-disabled="true"]) {
    --mc-image: var(--mc-disabled-image);
    --mc-border: var(--mc-disabled-border);
    --mc-ink: #a0a0a0;
    --mc-shadow: #282828;
    --mc-piece-0: var(--mc-disabled-0);
    --mc-piece-1: var(--mc-disabled-1);
    --mc-piece-2: var(--mc-disabled-2);
    --mc-piece-3: var(--mc-disabled-3);
    --mc-piece-4: var(--mc-disabled-4);
    --mc-piece-5: var(--mc-disabled-5);
    --mc-piece-6: var(--mc-disabled-6);
    --mc-piece-7: var(--mc-disabled-7);
    --mc-piece-8: var(--mc-disabled-8);
    cursor: default;
  }
  .mc-button-surface {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-columns: var(--mc-border-px) minmax(0, 1fr) var(--mc-border-px);
    grid-template-rows: var(--mc-border-px) minmax(0, 1fr) var(--mc-border-px);
    pointer-events: none;
    text-shadow: none;
  }
  .mc-button-surface > span { background-repeat: repeat; }
  .mc-button-surface > :nth-child(1) { background-image: var(--mc-piece-0); }
  .mc-button-surface > :nth-child(2) { background-image: var(--mc-piece-1); }
  .mc-button-surface > :nth-child(3) { background-image: var(--mc-piece-2); }
  .mc-button-surface > :nth-child(4) { background-image: var(--mc-piece-3); }
  .mc-button-surface > :nth-child(5) { background-image: var(--mc-piece-4); }
  .mc-button-surface > :nth-child(6) { background-image: var(--mc-piece-5); }
  .mc-button-surface > :nth-child(7) { background-image: var(--mc-piece-6); }
  .mc-button-surface > :nth-child(8) { background-image: var(--mc-piece-7); }
  .mc-button-surface > :nth-child(9) { background-image: var(--mc-piece-8); }
  .mc-button-surface > :is(:nth-child(1), :nth-child(3), :nth-child(7), :nth-child(9)) {
    background-size: var(--mc-border-px) var(--mc-border-px);
  }
  .mc-button-surface > :is(:nth-child(2), :nth-child(8)) {
    background-size: var(--mc-tile-width) var(--mc-border-px);
  }
  .mc-button-surface > :is(:nth-child(4), :nth-child(6)) {
    background-size: var(--mc-border-px) var(--mc-tile-height);
  }
  .mc-button-surface > :nth-child(5) {
    background-size: var(--mc-tile-width) var(--mc-tile-height);
  }
  .mc-button-label {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: calc(4 * var(--mc-pixel));
  }
  .mc-button > .mc-button-label {
    position: absolute;
    left: round(down, 50%, var(--mc-pixel));
    top: calc(round(down, (100% - 9 * var(--mc-pixel)) / 2, var(--mc-pixel)) + var(--mc-pixel));
    transform: translateX(round(up, -50%, var(--mc-pixel)));
  }
  .mc-text, .mc-text-pixels { display: inline-flex; }
  .mc-text-pixels { filter: drop-shadow(var(--mc-pixel) var(--mc-pixel) 0 var(--mc-shadow)); }
  .mc-glyph {
    display: block;
    width: calc(var(--mc-advance) * var(--mc-pixel));
    height: calc(8 * var(--mc-pixel));
    flex-shrink: 0;
    background-color: var(--mc-ink);
    mask-image: var(--mc-ascii-atlas);
    mask-size: calc(var(--mc-atlas-size) * var(--mc-pixel)) calc(var(--mc-atlas-size) * var(--mc-pixel));
    mask-position: calc(-1 * var(--mc-glyph-x) * var(--mc-pixel)) calc(-1 * var(--mc-glyph-y) * var(--mc-pixel));
    mask-repeat: no-repeat;
  }
  .mc-text-accessible {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }
}
